8d64581dc1d29648:
#part_page("I", [एक अनुरोध की लागत], [
  कोई एल्गोरिदम चुनने से पहले तय करें कि उसे किस संसाधन की रक्षा करनी है। यह अध्याय origin के काम, puzzle के काम, sessions और उस मेमोरी के मॉडल बनाता है जिसे एक अविश्वसनीय client server पर बनाए रखने के लिए बाध्य कर सकता है। आगे के अध्याय इन्हीं मॉडलों से डिज़ाइन के विकल्पों का मूल्यांकन करते हैं।
])

57c9f006a37b51ce:
#objectives([
  इस अध्याय के बाद आप गणना कर सकेंगे कि gate से origin का काम बचता है या नहीं। आप बता सकेंगे कि proof of work क्या स्थापित करता है। आप hash search का औसत और tail निकाल सकेंगे, समझा सकेंगे कि sessions कैसे puzzle की लागत को कई अनुरोधों में बाँटते हैं, और इस पुस्तक के पाँच invariants बता सकेंगे।
])

de29137d766efee7:
#definition([उदाहरण: gate कब अपनी लागत की भरपाई करता है], [
  ⟦0⟧ कार्य इकाइयाँ और ⟦1⟧ चुनें। यदि आधे अनुरोध अस्वीकृत हों, तो gate वाला सिस्टम हर आगमन पर 100 के बजाय ⟦2⟧ इकाइयाँ खर्च करता है। यदि एक हज़ार में केवल एक अनुरोध अस्वीकृत हो, तो खर्च ⟦3⟧ होता है। इस मॉडल में gate की लागत उसकी बचत से अधिक है। ये चुनी हुई संख्याएँ timings नहीं हैं। वे दिखाती हैं कि हर performance दावे में workload का उल्लेख क्यों होना चाहिए।
])

d2a1e04c685cd3bd:
#definition([उदाहरण: अपेक्षित मान समय सीमा नहीं है], [
  ⟦0⟧ पर अपेक्षित काम 65,536 hashes है। इतने प्रयासों के बाद भी खोज जारी रहने की संभावना लगभग ⟦1⟧ है। प्रयासों का 95वाँ percentile ⟦2⟧ है, जो औसत से लगभग तीन गुना है। User interface को इस अंतर की गुंजाइश रखनी चाहिए। अपेक्षित completion time पर failure घोषित नहीं करना चाहिए।
])

42847138e9e63cd0:
#teach_back([
  Gate की असमता ⟦0⟧ को शब्दों में समझाएँ। फिर बताएँ कि केवल measured verification latency से operator क्यों नहीं तय कर सकता कि gate चलाना लाभकारी है या नहीं।
])
